        for (i, button) in buttons.enumerated() {
            print("Button \(i): label='\(button.label)', id='\(button.identifier)', hittable=\(button.isHittable)")
        }

        // Look for repost button
        let repostButtons = app.buttons.matching(NSPredicate(format: "label CONTAINS 'Repost'"))
